def transform(grid):
    result = deepcopy(grid)

    if not grid or not grid[0]:
        return result

    counter = Counter()
    for row in grid:
        for val in row:
            counter[val] += 1

    bg = max(counter, key=counter.get)
    fill = 2

    rows = len(grid)
    cols = len(grid[0])

    # Precompute: for each cell, does it have markers horizontally and vertically?
    has_horizontal_markers = set()  # cells with markers in same row
    has_vertical_markers = set()    # cells with markers in same column

    for r in range(rows):
        markers_row = [c for c in range(cols) if grid[r][c] != bg]
        if len(markers_row) >= 2:
            min_m, max_m = markers_row[0], markers_row[-1]
            for c in range(min_m + 1, max_m):
                has_horizontal_markers.add((r, c))

    for c in range(cols):
        markers_col = [r for r in range(rows) if grid[r][c] != bg]
        if len(markers_col) >= 2:
            min_m, max_m = markers_col[0], markers_col[-1]
            for r in range(min_m + 1, max_m):
                has_vertical_markers.add((r, c))

    # Fill cells that have BOTH horizontal AND vertical markers
    fills = set()

    # Check horizontal markers in rows
    for r in range(rows):
        markers_row = [c for c in range(cols) if grid[r][c] != bg]
        if len(markers_row) >= 2:
            min_m, max_m = markers_row[0], markers_row[-1]
            for c in range(min_m + 1, max_m):
                if grid[r][c] == bg:
                    if (r, c) in has_horizontal_markers:
                        fills.add((r, c))

    # Check vertical markers in columns
    for c in range(cols):
        markers_col = [r for r in range(rows) if grid[r][c] != bg]
        if len(markers_col) >= 2:
            min_m, max_m = markers_col[0], markers_col[-1]
            for r in range(min_m + 1, max_m):
                if grid[r][c] == bg:
                    if (r, c) in has_vertical_markers:
                        fills.add((r, c))

    # Apply fills
    for r, c in fills:
        result[r][c] = fill

    return result
